#!/usr/bin/env bash
# tools/build-readme.sh — Generate README.md from docs/readme/*.md and demo/transcripts/*.txt

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
README_OUT="$ROOT/README.md"
README_PARTS="$ROOT/docs/readme"
TRANSCRIPTS="$ROOT/demo/transcripts"

# Header comment
cat > "$README_OUT" <<'EOF'
<!-- generated by tools/build-readme.sh; do not edit -->

EOF

# Concatenate all markdown parts in lexicographic order
for part in "$README_PARTS"/*.md; do
  cat "$part" >> "$README_OUT"
  echo "" >> "$README_OUT"
done

# Replace include markers with transcript content
# This is done in a second pass to handle the includes properly
awk -v transcripts="$TRANSCRIPTS" '
  /<!-- include:transcript:([^>]+) -->/ {
    match($0, /<!-- include:transcript:([^>]+) -->/, m)
    transcript = m[1]
    print "```console"
    while ((getline line < (transcripts "/" transcript)) > 0) {
      print line
    }
    close(transcripts "/" transcript)
    print "```"
    next
  }
  { print }
' "$README_OUT" > "$README_OUT.tmp" && mv "$README_OUT.tmp" "$README_OUT"

echo "Generated $README_OUT"